1	import Phaser from 'phaser';
2	import { KEYS } from '../config/assetManifest';
3	
4	/**
5	 * HeroDog — the player avatar.
6	 *
7	 * Phase 1 is a PLACEHOLDER: it renders the run sprite pinned at a fixed screen X
8	 * (the world will scroll past it later) with a gentle idle bob, plus a cosmetic
9	 * squash-hop on tap to prove the input path end-to-end. No physics/HP yet.
10	 *
11	 * Phase 2 turns this into a `Phaser.Physics.Arcade.Sprite` with HP and the five
12	 * animation states (run/jump/hit/victory/defeat) — the class boundary is here so
13	 * that is an additive change, not a rewrite.
14	 */
15	export class HeroDog extends Phaser.GameObjects.Sprite {
16	  constructor(scene: Phaser.Scene, x: number, y: number) {
17	    super(scene, x, y, KEYS.dog_run);
18	    this.setOrigin(0.5, 1); // feet rest on the ground line at `y`
19	    scene.add.existing(this);
20	
21	    // Idle bob so the placeholder reads as "alive".
22	    scene.tweens.add({
23	      targets: this,
24	      y: y - 6,
25	      duration: 420,
26	      yoyo: true,
27	      repeat: -1,
28	      ease: 'Sine.inOut',
29	    });
30	  }
31	
32	  /** Cosmetic squash-hop on tap (Phase 1 has no real jump physics yet). */
33	  nudgeJump(): void {
34	    this.scene.tweens.add({
35	      targets: this,
36	      scaleX: 1.08,
37	      scaleY: 0.9,
38	      duration: 90,
39	      yoyo: true,
40	      ease: 'Quad.out',
41	    });
42	  }
43	}
