import Phaser from 'phaser';

/**
 * RunnerEntity — shared base for every POOLED, world-scrolling entity (ticks,
 * tablets, obstacles, armor pickups, finish line).
 *
 * Pooling contract (spec §10.1 — no per-spawn GC churn):
 *  - Instances live in a `Phaser.Physics.Arcade.Group` (the pool) and are reused.
 *  - `group.get()` hands back a dead instance (or constructs one up to maxSize);
 *    the scene/spawner then calls `spawn(x, y)` to make it live at a position.
 *  - `recycle()` disables the body + hides it, returning it to the pool for reuse.
 *
 * Horizontal motion is driven by the Spawner setting `body.velocity.x` to the
 * current world speed each frame, so entities stay in lock-step with the parallax
 * and the distance metric (1 world unit == 1 px). None of these entities use
 * gravity — they float at their spawn Y and scroll left.
 */
export abstract class RunnerEntity extends Phaser.Physics.Arcade.Sprite {
  /** Reactivate this pooled entity at (x, y) with a live, gravity-free body. */
  spawn(x: number, y: number): this {
    // enableBody(reset, x, y, enableGameObject, showGameObject)
    this.enableBody(true, x, y, true, true);
    this.setActive(true);
    this.setVisible(true);
    this.setScale(1);
    this.setAlpha(1);
    this.setAngle(0);

    const body = this.body as Phaser.Physics.Arcade.Body;
    body.setAllowGravity(false);
    body.setVelocity(0, 0);
    this.configureBody(body);
    return this;
  }

  /** Return to the pool: disable body, hide, deactivate (so `group.get` reuses it). */
  recycle(): void {
    if (!this.active) return;
    // disableBody(disableGameObject, hideGameObject)
    this.disableBody(true, true);
  }

  /** Whether this entity has scrolled far enough off-screen to be recycled. */
  isOffscreenLeft(recycleX: number): boolean {
    return this.active && this.x < recycleX;
  }

  /**
   * Size/position the Arcade body once it is live. Default: a centered box scaled
   * to `hitboxScale` of the art frame — forgiving for the player. Subclasses may
   * override for a non-centered or full-height body (e.g. the finish line).
   */
  protected configureBody(body: Phaser.Physics.Arcade.Body): void {
    const scale = this.hitboxScale();
    body.setSize(this.width * scale, this.height * scale, true);
  }

  /** Fraction of the art frame used for the (centered) hitbox. */
  protected abstract hitboxScale(): number;
}

import Phaser from 'phaser';
import { KEYS } from '../config/assetManifest';
import { HAZARD_HITBOX_SCALE } from '../config/gameConfig';
import { RunnerEntity } from './RunnerEntity';

/**
 * Tick — the signature damaging enemy (spec §3.3). A ground hazard: collision
 * costs the hero −1 HP (unless armored/invulnerable). Anchored bottom-center on
 * the ground line, faces right (no flip). A gentle idle wobble is applied by the
 * Spawner via a shared tween so pooled instances animate without per-entity work.
 */
export class Tick extends RunnerEntity {
  constructor(scene: Phaser.Scene, x = 0, y = 0) {
    super(scene, x, y, KEYS.tick);
    this.setOrigin(0.5, 1); // ground entity → feet on the ground line
  }

  protected hitboxScale(): number {
    return HAZARD_HITBOX_SCALE;
  }
}

import Phaser from 'phaser';
import { KEYS } from '../config/assetManifest';
import { HAZARD_HITBOX_SCALE } from '../config/gameConfig';
import { RunnerEntity } from './RunnerEntity';

/**
 * Environmental obstacles (spec §3.3) — bush & puddle. Same damage model as a
 * tick (−1 HP), treated as jump-over hazards. Both are ground entities anchored
 * bottom-center. Split into two thin classes so each backs its own object pool
 * (a pool is single-texture), while sharing the ground-hazard hitbox.
 */
abstract class GroundObstacle extends RunnerEntity {
  protected hitboxScale(): number {
    return HAZARD_HITBOX_SCALE;
  }
}

/** Bush — a tall-ish jump obstacle. */
export class Bush extends GroundObstacle {
  constructor(scene: Phaser.Scene, x = 0, y = 0) {
    super(scene, x, y, KEYS.bush);
    this.setOrigin(0.5, 1);
  }
}

/** Puddle — a low, wide jump obstacle. */
export class Puddle extends GroundObstacle {
  constructor(scene: Phaser.Scene, x = 0, y = 0) {
    super(scene, x, y, KEYS.puddle);
    this.setOrigin(0.5, 1);
  }
}

import Phaser from 'phaser';
import { KEYS } from '../config/assetManifest';
import { PICKUP_HITBOX_SCALE } from '../config/gameConfig';
import { RunnerEntity } from './RunnerEntity';

/**
 * Tablet — the brand product collectible (spec §3.3). Pickup grants +score and
 * +1 HP (capped at the 3-heart max). Hovers above the ground (placed by the
 * Spawner) so collecting it requires a jump — the same jump that clears hazards.
 * Centered origin so it floats; forgiving hitbox so it's easy to grab.
 */
export class Tablet extends RunnerEntity {
  constructor(scene: Phaser.Scene, x = 0, y = 0) {
    super(scene, x, y, KEYS.tablet);
    this.setOrigin(0.5, 0.5); // floating collectible
  }

  protected hitboxScale(): number {
    return PICKUP_HITBOX_SCALE;
  }
}

import Phaser from 'phaser';
import { KEYS } from '../config/assetManifest';
import { PICKUP_HITBOX_SCALE } from '../config/gameConfig';
import { RunnerEntity } from './RunnerEntity';

/**
 * ArmorPickup — the "tablet as armor" shield power-up (spec §3.7). Pickup grants
 * timed total invulnerability. Occasional (~1–2/level). Hovers above the ground
 * like a tablet (jump to collect); centered origin so it floats.
 */
export class ArmorPickup extends RunnerEntity {
  constructor(scene: Phaser.Scene, x = 0, y = 0) {
    super(scene, x, y, KEYS.armor_pickup);
    this.setOrigin(0.5, 0.5);
  }

  protected hitboxScale(): number {
    return PICKUP_HITBOX_SCALE;
  }
}

import Phaser from 'phaser';
import { KEYS } from '../config/assetManifest';
import { FINISH_HITBOX_WIDTH } from '../config/gameConfig';
import { RunnerEntity } from './RunnerEntity';

/**
 * FinishLine — spawned ONCE at world position LEVEL_LENGTH (spec §3.9). Reaching
 * it with ≥1 HP ends the run in Victory. Ground entity anchored bottom-center; a
 * thin, FULL-HEIGHT trigger band so the overlap fires whether the hero is grounded
 * or mid-jump when it arrives. Pooled via a 1-slot group for API consistency.
 */
export class FinishLine extends RunnerEntity {
  constructor(scene: Phaser.Scene, x = 0, y = 0) {
    super(scene, x, y, KEYS.finish_line);
    this.setOrigin(0.5, 1);
  }

  protected hitboxScale(): number {
    return 1; // unused — configureBody is overridden below
  }

  protected override configureBody(body: Phaser.Physics.Arcade.Body): void {
    // Thin horizontally, full art height, centered → catches any jump height.
    body.setSize(FINISH_HITBOX_WIDTH, this.height, true);
  }
}

import Phaser from 'phaser';
import { KEYS } from '../config/assetManifest';
import {
  GRAVITY_Y,
  JUMP_VELOCITY_Y,
  MAX_HP,
  START_HP,
  INVULN_MS,
  INVULN_BLINK_MS,
  ARMOR_DURATION_MS,
  ARMOR_EXPIRY_TELL_MS,
  ARMOR_AURA_BLINK_MS,
  HERO_BODY_WIDTH,
  HERO_BODY_HEIGHT,
  HERO_RUN_TILT_DEG,
  HERO_RUN_TILT_MS,
  HERO_JUMP_STRETCH,
  HERO_JUMP_STRETCH_MS,
  HERO_LAND_SQUASH,
  HERO_LAND_SQUASH_MS,
  HERO_HIT_POSE_MS,
  HIT_FLASH_MS,
  HERO_VICTORY_HOP_VELOCITY,
} from '../config/gameConfig';

/** Visual/logic state of the hero (spec §4.1 — the five animation states). */
export type HeroState = 'run' | 'jump' | 'hit' | 'victory' | 'defeat';

/**
 * HeroDog — the player avatar (spec §3.3, §3.4, §3.7).
 *
 * An Arcade-physics sprite pinned at a fixed screen X while the world scrolls past
 * (the Spawner/parallax move; the dog only moves vertically). Owns:
 *  - a run → jump → hit → victory/defeat state machine (single SVG per state);
 *  - HP with a post-hit invulnerability (i-frame) window so one contact can't
 *    drain multiple hearts (§3.4);
 *  - the Armor power-up: timed total invulnerability with a `dog_armored` art swap,
 *    a persistent aura, and an expiry blink tell (§3.7 / §4.4).
 *
 * Animation is done with tweens on body-safe channels: run uses an ANGLE tilt
 * (Arcade AABBs ignore rotation, so the hitbox never wobbles); jump squash/stretch
 * scales briefly only at takeoff/landing (never mid-air where collectibles are
 * grabbed); i-frames blink ALPHA. The scene drives per-frame work via `tick()`.
 */
export class HeroDog extends Phaser.Physics.Arcade.Sprite {
  hp = START_HP;

  private heroState: HeroState = 'run';
  private grounded = true;
  private armorUntil = 0;
  private invulnUntil = 0;

  /** Persistent shield aura shown while armored; follows the dog in `tick()`. */
  private readonly aura: Phaser.GameObjects.Image;

  private runTilt?: Phaser.Tweens.Tween;
  private blink?: Phaser.Tweens.Tween;
  private hitPoseTimer?: Phaser.Time.TimerEvent;
  private flashTimer?: Phaser.Time.TimerEvent;

  constructor(scene: Phaser.Scene, x: number, y: number) {
    super(scene, x, y, KEYS.dog_run);
    this.setOrigin(0.5, 1); // feet rest on the ground line at `y`
    scene.add.existing(this);
    scene.physics.add.existing(this);

    const body = this.body as Phaser.Physics.Arcade.Body;
    body.setGravityY(GRAVITY_Y);
    body.setVelocity(0, 0);
    this.applyBody();

    // Aura sits just above the hero; created hidden, shown on armor pickup.
    this.aura = scene.add.image(x, y, KEYS.vfx_armor_aura).setOrigin(0.5, 0.5);
    this.aura.setVisible(false).setActive(false);

    this.enterRun();
  }

  // ── Public state queries (also power the Phase-4 HUD hooks) ────────────────
  get state(): HeroState {
    return this.heroState;
  }

  get isAlive(): boolean {
    return this.heroState !== 'defeat' && this.heroState !== 'victory';
  }

  isArmored(time: number): boolean {
    return time < this.armorUntil;
  }

  /** True while EITHER armor or the post-hit i-frame window is active. */
  isInvulnerable(time: number): boolean {
    return time < this.armorUntil || time < this.invulnUntil;
  }

  /** Milliseconds of armor remaining (0 if not armored) — for the HUD/audio tell. */
  armorRemaining(time: number): number {
    return Math.max(0, this.armorUntil - time);
  }

  /** The shared aura game object (so the scene can order its depth once). */
  get auraSprite(): Phaser.GameObjects.Image {
    return this.aura;
  }

  // ── Input ──────────────────────────────────────────────────────────────────
  /** Edge-triggered jump: fires only when grounded & alive; ignored airborne. */
  jump(): void {
    if (!this.isAlive || !this.grounded) return;
    const body = this.body as Phaser.Physics.Arcade.Body;
    body.setVelocityY(JUMP_VELOCITY_Y);
    this.grounded = false;
    this.enterJump();
  }

  // ── Damage / heal / armor ───────────────────────────────────────────────────
  /**
   * Apply `amount` damage. Returns true only if HP was actually removed (false
   * when invulnerable) so the caller knows whether to consume the hazard / react.
   * i-frames are what stop a single lingering contact from draining several HP.
   */
  takeHit(time: number, amount: number): boolean {
    if (!this.isAlive || this.isInvulnerable(time)) return false;

    this.hp = Math.max(0, this.hp - amount);
    this.invulnUntil = time + INVULN_MS;
    this.enterHit();
    this.startBlink();
    return true;
  }

  /** Heal by `amount`, capped at the 3-heart max (spec §3.4). */
  heal(amount: number): void {
    this.hp = Math.min(MAX_HP, this.hp + amount);
  }

  /** Activate the Armor power-up: timed total invulnerability + art swap (§3.7). */
  activateArmor(time: number): void {
    this.armorUntil = time + ARMOR_DURATION_MS;
    this.aura.setVisible(true).setActive(true).setAlpha(1);
    // Post-hit blink is redundant under armor — clear it for a clean aura read.
    this.stopBlink();
    if (this.heroState === 'run') this.setHeroTexture(KEYS.dog_armored);
  }

  // ── Terminal poses ───────────────────────────────────────────────────────────
  victory(): void {
    if (!this.isAlive) return;
    this.enterEnd('victory');
    const body = this.body as Phaser.Physics.Arcade.Body;
    // Re-enable a brief hop for celebration, then let it settle.
    body.setVelocity(0, HERO_VICTORY_HOP_VELOCITY);
    this.scene.tweens.add({
      targets: this,
      scaleX: 1.06,
      scaleY: 0.94,
      duration: 160,
      yoyo: true,
      ease: 'Quad.out',
    });
  }

  defeat(): void {
    if (!this.isAlive) return;
    this.enterEnd('defeat');
    this.scene.tweens.add({
      targets: this,
      angle: -8,
      duration: 220,
      ease: 'Quad.out',
    });
  }

  // ── Per-frame update (called by the scene) ──────────────────────────────────
  tick(time: number): void {
    const body = this.body as Phaser.Physics.Arcade.Body | null;

    if (this.heroState === 'victory' || this.heroState === 'defeat') {
      this.aura.setVisible(false);
      return;
    }

    // Landing detection: a jump that has touched the floor returns to run.
    if (body) {
      const onFloor = body.onFloor();
      if (onFloor && !this.grounded && this.heroState === 'jump') {
        this.grounded = true;
        this.onLanded();
      }
      this.grounded = onFloor;
    }

    // Armor lifetime + expiry tell.
    if (this.armorUntil > 0) {
      if (time >= this.armorUntil) {
        this.deactivateArmor();
      } else {
        this.updateAura(time);
      }
    }

    // i-frame expiry (independent of armor).
    if (this.invulnUntil > 0 && time >= this.invulnUntil) {
      this.stopBlink();
    }
  }

  // ── State entry helpers ──────────────────────────────────────────────────────
  private enterRun(): void {
    this.heroState = 'run';
    this.setHeroTexture(this.isArmored(this.scene.time.now) ? KEYS.dog_armored : KEYS.dog_run);
    this.setScale(1);
    this.startRunTilt();
  }

  private enterJump(): void {
    this.heroState = 'jump';
    this.setHeroTexture(KEYS.dog_jump);
    this.stopRunTilt();
    this.setAngle(0);
    // Takeoff stretch — brief, resets to 1 well before apex (mid-air stays true).
    this.scene.tweens.add({
      targets: this,
      scaleX: 1 - HERO_JUMP_STRETCH,
      scaleY: 1 + HERO_JUMP_STRETCH,
      duration: HERO_JUMP_STRETCH_MS,
      yoyo: true,
      ease: 'Quad.out',
    });
  }

  private onLanded(): void {
    // Landing squash, then settle into the run loop.
    this.scene.tweens.add({
      targets: this,
      scaleX: 1 + HERO_LAND_SQUASH,
      scaleY: 1 - HERO_LAND_SQUASH,
      duration: HERO_LAND_SQUASH_MS,
      yoyo: true,
      ease: 'Quad.out',
    });
    this.enterRun();
  }

  private enterHit(): void {
    this.heroState = 'hit';
    this.setHeroTexture(KEYS.dog_hit);
    this.stopRunTilt();

    // Red flash on the dog.
    this.setTint(0xff6b6b);
    this.flashTimer?.remove();
    this.flashTimer = this.scene.time.delayedCall(HIT_FLASH_MS, () => this.clearTint());

    // Hold the hit pose briefly, then return to run/jump (unless the run ended).
    this.hitPoseTimer?.remove();
    this.hitPoseTimer = this.scene.time.delayedCall(HERO_HIT_POSE_MS, () => {
      if (this.heroState !== 'hit') return;
      if (this.grounded) this.enterRun();
      else {
        this.heroState = 'jump';
        this.setHeroTexture(KEYS.dog_jump);
      }
    });
  }

  private enterEnd(which: 'victory' | 'defeat'): void {
    this.heroState = which;
    this.stopRunTilt();
    this.stopBlink();
    this.flashTimer?.remove();
    this.hitPoseTimer?.remove();
    this.clearTint();
    this.setAngle(0);
    this.aura.setVisible(false).setActive(false);
    this.setHeroTexture(which === 'victory' ? KEYS.dog_victory : KEYS.dog_defeat);
  }

  private deactivateArmor(): void {
    this.armorUntil = 0;
    this.aura.setVisible(false).setActive(false);
    if (this.heroState === 'run') this.setHeroTexture(KEYS.dog_run);
  }

  // ── Tween/visual utilities ──────────────────────────────────────────────────
  private updateAura(time: number): void {
    // Aura rides the dog's torso.
    this.aura.setPosition(this.x, this.y - HERO_BODY_HEIGHT * 0.55);
    // Expiry tell: blink in the final window (spec §4.4).
    const remaining = this.armorUntil - time;
    if (remaining <= ARMOR_EXPIRY_TELL_MS) {
      const on = Math.floor(time / ARMOR_AURA_BLINK_MS) % 2 === 0;
      this.aura.setAlpha(on ? 1 : 0.25);
    } else {
      this.aura.setAlpha(1);
    }
  }

  private startRunTilt(): void {
    this.stopRunTilt();
    this.setAngle(0);
    this.runTilt = this.scene.tweens.add({
      targets: this,
      angle: { from: -HERO_RUN_TILT_DEG, to: HERO_RUN_TILT_DEG },
      duration: HERO_RUN_TILT_MS,
      yoyo: true,
      repeat: -1,
      ease: 'Sine.inOut',
    });
  }

  private stopRunTilt(): void {
    this.runTilt?.stop();
    this.runTilt = undefined;
  }

  private startBlink(): void {
    this.stopBlink();
    this.blink = this.scene.tweens.add({
      targets: this,
      alpha: 0.3,
      duration: INVULN_BLINK_MS,
      yoyo: true,
      repeat: -1,
    });
  }

  private stopBlink(): void {
    this.blink?.stop();
    this.blink = undefined;
    this.setAlpha(1);
  }

  /** Swap the state SVG and re-fit the (feet-anchored) physics body to it. */
  private setHeroTexture(key: string): void {
    if (this.texture.key === key) return;
    this.setTexture(key);
    this.setOrigin(0.5, 1);
    if (this.body) this.applyBody();
  }

  /**
   * Fit a forgiving, feet-anchored body to the current frame. With origin (0.5,1)
   * and this offset, the body's bottom sits exactly on the sprite's y (the feet),
   * horizontally centered — so the ground collider rests the dog correctly and the
   * hitbox stays fair as textures swap between differently-sized state frames.
   */
  private applyBody(): void {
    const body = this.body as Phaser.Physics.Arcade.Body;
    const fw = this.width;
    const fh = this.height;
    body.setSize(HERO_BODY_WIDTH, HERO_BODY_HEIGHT, false);
    body.setOffset((fw - HERO_BODY_WIDTH) / 2, fh - HERO_BODY_HEIGHT);
  }
}

import Phaser from 'phaser';
import {
  LEVEL_LENGTH,
  SCROLL_SPEED_START,
  SCROLL_SPEED_MAX,
  HAZARD_SPACING_START,
  HAZARD_SPACING_END,
  TABLET_SPACING_START,
  LATE_GENEROSITY_FACTOR,
} from '../config/gameConfig';

/**
 * DifficultyCurve — the authored ramp over the finite level (spec §3.8).
 *
 * Pure, stateless functions of `progress` (distance / LEVEL_LENGTH, clamped to
 * [0,1]) so the ramp is repeatable and tunable entirely from gameConfig:
 *  - world SPEED rises start → max;
 *  - hazard SPACING tightens start → end (always jump-clearable, §3.2);
 *  - collectible GENEROSITY tapers in the final quarter to raise late tension,
 *    which WIDENS tablet spacing near the finish.
 */
export class DifficultyCurve {
  /** Fraction of the level completed, from distance travelled. */
  progress(distance: number): number {
    return Phaser.Math.Clamp(distance / LEVEL_LENGTH, 0, 1);
  }

  /** World scroll speed (px/s) at this progress. */
  speed(progress: number): number {
    return Phaser.Math.Linear(SCROLL_SPEED_START, SCROLL_SPEED_MAX, progress);
  }

  /** Center-to-center world spacing (== on-screen px) between consecutive hazards. */
  hazardSpacing(progress: number): number {
    return Phaser.Math.Linear(HAZARD_SPACING_START, HAZARD_SPACING_END, progress);
  }

  /**
   * Collectible generosity multiplier: 1.0 until the final quarter, then eases to
   * LATE_GENEROSITY_FACTOR by the finish (fewer freebies near the end).
   */
  generosity(progress: number): number {
    if (progress <= 0.75) return 1;
    const tail = (progress - 0.75) / 0.25; // 0 → 1 across the last quarter
    return Phaser.Math.Linear(1, LATE_GENEROSITY_FACTOR, tail);
  }

  /** World spacing between tablets — widens as generosity tapers late-game. */
  tabletSpacing(progress: number): number {
    return TABLET_SPACING_START / this.generosity(progress);
  }
}

import Phaser from 'phaser';
import { Tick } from '../entities/Tick';
import { Bush, Puddle } from '../entities/Obstacle';
import { Tablet } from '../entities/Tablet';
import { ArmorPickup } from '../entities/ArmorPickup';
import { RunnerEntity } from '../entities/RunnerEntity';
import { DifficultyCurve } from './DifficultyCurve';
import {
  LEVEL_LENGTH,
  HAZARD_SPACING_START,
  TABLET_SPACING_START,
  ARMOR_SPAWNS_PER_LEVEL,
  POOL_SIZE_HAZARD,
  POOL_SIZE_TABLET,
  POOL_SIZE_ARMOR,
  COLLECTIBLE_HOVER_PX,
  COLLECTIBLE_HOVER_JITTER_PX,
  HAZARD_WEIGHT_TICK,
  HAZARD_WEIGHT_BUSH,
  HAZARD_WEIGHT_PUDDLE,
} from '../config/gameConfig';

interface HazardChoice {
  readonly group: Phaser.Physics.Arcade.Group;
  readonly weight: number;
}

/**
 * Spawner — difficulty-curve-driven spawning from OBJECT POOLS (spec §3.8, §10.1).
 *
 * Every scrolling entity lives in a `Phaser.Physics.Arcade.Group` sized above the
 * worst-case on-screen count, so `update()` never allocates — it reuses dead
 * instances via `group.get()` and returns them with `recycle()`. No per-spawn GC.
 *
 * Spawning is DISTANCE-scheduled: because entities move left at exactly the world
 * speed and the distance metric advances at the same rate, scheduling a spawn every
 * `S` world-units yields a clean `S` px on-screen gap regardless of the speed ramp.
 * That keeps hazard spacing FAIR and jump-clearable (§3.2) — hazards sit on the
 * ground; tablets/armor hover so the same jump both clears a hazard and collects.
 */
export class Spawner {
  readonly tickPool: Phaser.Physics.Arcade.Group;
  readonly bushPool: Phaser.Physics.Arcade.Group;
  readonly puddlePool: Phaser.Physics.Arcade.Group;
  readonly tabletPool: Phaser.Physics.Arcade.Group;
  readonly armorPool: Phaser.Physics.Arcade.Group;

  private readonly allPools: Phaser.Physics.Arcade.Group[];
  private readonly hazardTable: HazardChoice[];
  private readonly hazardWeightTotal: number;

  private nextHazardDistance = HAZARD_SPACING_START;
  private nextTabletDistance = TABLET_SPACING_START;
  private readonly armorQueue: number[] = [];
  private spawningEnabled = true;

  constructor(
    private readonly scene: Phaser.Scene,
    private readonly curve: DifficultyCurve,
    private readonly groundY: number,
    private readonly spawnX: number,
    private readonly recycleX: number,
  ) {
    const mk = (classType: Function, maxSize: number): Phaser.Physics.Arcade.Group =>
      scene.physics.add.group({ classType, maxSize, runChildUpdate: false });

    this.tickPool = mk(Tick, POOL_SIZE_HAZARD);
    this.bushPool = mk(Bush, POOL_SIZE_HAZARD);
    this.puddlePool = mk(Puddle, POOL_SIZE_HAZARD);
    this.tabletPool = mk(Tablet, POOL_SIZE_TABLET);
    this.armorPool = mk(ArmorPickup, POOL_SIZE_ARMOR);

    this.allPools = [this.tickPool, this.bushPool, this.puddlePool, this.tabletPool, this.armorPool];

    this.hazardTable = [
      { group: this.tickPool, weight: HAZARD_WEIGHT_TICK },
      { group: this.bushPool, weight: HAZARD_WEIGHT_BUSH },
      { group: this.puddlePool, weight: HAZARD_WEIGHT_PUDDLE },
    ];
    this.hazardWeightTotal = this.hazardTable.reduce((s, h) => s + h.weight, 0);

    this.buildArmorSchedule();
  }

  /** Pools whose contact costs the hero HP (tick behaves specially under armor). */
  get obstaclePools(): Phaser.Physics.Arcade.Group[] {
    return [this.bushPool, this.puddlePool];
  }

  /**
   * Advance the run one frame: schedule new spawns from the curve, then scroll and
   * recycle every active entity. `distance` is world units travelled so far.
   */
  update(distance: number, worldSpeed: number, progress: number): void {
    if (this.spawningEnabled) {
      while (distance >= this.nextHazardDistance) {
        this.spawnHazard();
        this.nextHazardDistance += this.curve.hazardSpacing(progress);
      }
      while (distance >= this.nextTabletDistance) {
        this.spawnTablet();
        this.nextTabletDistance += this.curve.tabletSpacing(progress);
      }
      while (this.armorQueue.length > 0 && distance >= this.armorQueue[0]!) {
        this.armorQueue.shift();
        this.spawnArmor();
      }
    }

    this.scrollAndRecycle(worldSpeed);
  }

  /** Stop scheduling NEW spawns (called once the finish line is queued, §3.9). */
  stopSpawning(): void {
    this.spawningEnabled = false;
  }

  /** Recycle everything currently live (e.g. on a clean restart). */
  recycleAll(): void {
    for (const pool of this.allPools) {
      for (const child of pool.getChildren()) {
        (child as RunnerEntity).recycle();
      }
    }
  }

  destroy(): void {
    for (const pool of this.allPools) pool.destroy(true);
  }

  // ── Spawning ─────────────────────────────────────────────────────────────────
  private spawnHazard(): void {
    const pool = this.pickHazardPool();
    const entity = pool.get(this.spawnX, this.groundY) as RunnerEntity | null;
    if (!entity) return; // pool exhausted — skip (sized so this shouldn't happen)
    entity.spawn(this.spawnX, this.groundY); // ground entities: feet on the ground line
  }

  private spawnTablet(): void {
    const y = this.hoverY();
    const entity = this.tabletPool.get(this.spawnX, y) as RunnerEntity | null;
    if (!entity) return;
    entity.spawn(this.spawnX, y);
  }

  private spawnArmor(): void {
    const y = this.hoverY();
    const entity = this.armorPool.get(this.spawnX, y) as RunnerEntity | null;
    if (!entity) return;
    entity.spawn(this.spawnX, y);
  }

  /** A hover height above the ground that always requires a jump to reach. */
  private hoverY(): number {
    return this.groundY - COLLECTIBLE_HOVER_PX - Phaser.Math.Between(0, COLLECTIBLE_HOVER_JITTER_PX);
  }

  private pickHazardPool(): Phaser.Physics.Arcade.Group {
    const roll = Phaser.Math.Between(1, this.hazardWeightTotal);
    let acc = 0;
    for (const h of this.hazardTable) {
      acc += h.weight;
      if (roll <= acc) return h.group;
    }
    return this.tickPool; // unreachable; satisfies the type checker
  }

  private buildArmorSchedule(): void {
    const n = ARMOR_SPAWNS_PER_LEVEL;
    for (let i = 0; i < n; i++) {
      const frac = n === 1 ? 0.5 : Phaser.Math.Linear(0.25, 0.85, i / (n - 1));
      this.armorQueue.push(frac * LEVEL_LENGTH);
    }
  }

  // ── Motion / recycling ───────────────────────────────────────────────────────
  private scrollAndRecycle(worldSpeed: number): void {
    for (const pool of this.allPools) {
      for (const child of pool.getChildren()) {
        const e = child as RunnerEntity;
        if (!e.active) continue;
        e.setVelocityX(-worldSpeed);
        if (e.isOffscreenLeft(this.recycleX)) e.recycle();
      }
    }
  }
}

import Phaser from 'phaser';
import { SceneKey } from './keys';
import {
  GAME_WIDTH,
  GAME_HEIGHT,
  GROUND_TOP_Y,
  HERO_X,
  MAX_HP,
  TICK_DAMAGE,
  OBSTACLE_DAMAGE,
  TABLET_HEAL,
  TABLET_SCORE,
  SCORE_SURVIVAL_PER_S,
  LEVEL_LENGTH,
  SPAWN_MARGIN_PX,
  RECYCLE_MARGIN_PX,
  HERO_BODY_HEIGHT,
  PARALLAX_FACTOR_FAR,
  PARALLAX_FACTOR_NEAR,
  PARALLAX_FACTOR_GROUND,
  PARALLAX_FACTOR_GRASS,
  HIT_SHAKE_MS,
  HIT_SHAKE_INTENSITY,
  HIT_FLASH_MS,
  RESULTS_HANDOFF_DELAY_MS,
} from '../config/gameConfig';
import { KEYS } from '../config/assetManifest';
import { t } from '../i18n/strings';
import { track, type FinishGameParams } from '../analytics/track';
import { HeroDog } from '../entities/HeroDog';
import { FinishLine } from '../entities/FinishLine';
import { RunnerEntity } from '../entities/RunnerEntity';
import { DifficultyCurve } from '../systems/DifficultyCurve';
import { Spawner } from '../systems/Spawner';

/**
 * Events emitted on `scene.events` for a future HUD / AudioManager to subscribe to
 * (Phase 4). The in-scene HUD here is a throwaway readout; Phase 4's Hud.ts can
 * listen to these instead of reaching into the scene. Payloads are primitives.
 */
export const GameEvents = {
  hp: 'hud:hp', // (hp: number)
  score: 'hud:score', // (score: number)
  progress: 'hud:progress', // (progress: number 0..1)
  armor: 'hud:armor', // ({ active: boolean, remainingMs: number })
  runStart: 'run:start', // ()
  runEnd: 'run:end', // (payload: FinishGameParams)
} as const;

/** Render layering (presentation only). */
const Depth = {
  bgFar: 0,
  bgNear: 1,
  ground: 2,
  grass: 3,
  entity: 5,
  hero: 6,
  aura: 7,
  hud: 100,
} as const;

/**
 * GameScene — the real, finite core run loop (spec §3, §5.2, §8.3).
 *
 * The hero is pinned at HERO_X and only moves vertically; the WORLD scrolls past
 * (parallax tileSprites + object-pooled entities driven by the DifficultyCurve).
 * Fires `start_game` on entry and `finish_game` on Victory (finish line) or Game
 * Over (0 HP), then hands the SAME {result, score, duration_s} payload to
 * ResultsScene — the exact handoff the placeholder used.
 */
export class GameScene extends Phaser.Scene {
  private hero!: HeroDog;
  private curve!: DifficultyCurve;
  private spawner!: Spawner;
  private finishLine!: FinishLine;

  // Parallax layers.
  private bgFar!: Phaser.GameObjects.TileSprite;
  private bgNear!: Phaser.GameObjects.TileSprite;
  private groundTile!: Phaser.GameObjects.TileSprite;
  private fgGrass!: Phaser.GameObjects.TileSprite;

  // HUD readout.
  private heartImages: Phaser.GameObjects.Image[] = [];
  private scoreText!: Phaser.GameObjects.Text;
  private progressFill!: Phaser.GameObjects.Rectangle;

  // Run state.
  private distance = 0;
  private elapsedMs = 0;
  private tabletScore = 0;
  private score = 0;
  private finished = false;
  private finishSpawned = false;

  // Change-tracking so HUD events only fire on transitions.
  private lastHp = MAX_HP;
  private lastScore = 0;
  private lastArmorActive = false;

  private readonly spawnX = GAME_WIDTH + SPAWN_MARGIN_PX;
  private readonly recycleX = -RECYCLE_MARGIN_PX;
  /** Distance the hero covers while a right-edge spawn scrolls in to reach it. */
  private readonly approach = GAME_WIDTH + SPAWN_MARGIN_PX - HERO_X;

  constructor() {
    super({ key: SceneKey.Game });
  }

  create(): void {
    this.resetState();
    this.buildParallax();
    this.buildGroundAndHero();
    this.buildSystems();
    this.buildFinishLine();
    this.registerCollisions();
    this.buildHud();
    this.buildInput();

    // A round has begun (spec §5.2).
    track('start_game');
    this.events.emit(GameEvents.runStart);

    this.events.once(Phaser.Scenes.Events.SHUTDOWN, this.cleanup, this);
  }

  // ── Public read hooks (Phase 4 HUD/audio can poll these) ───────────────────
  get liveHp(): number {
    return this.hero.hp;
  }
  get liveScore(): number {
    return this.score;
  }
  get liveProgress(): number {
    return this.curve.progress(this.distance);
  }

  // ── Build steps ─────────────────────────────────────────────────────────────
  private resetState(): void {
    this.distance = 0;
    this.elapsedMs = 0;
    this.tabletScore = 0;
    this.score = 0;
    this.finished = false;
    this.finishSpawned = false;
    this.lastHp = MAX_HP;
    this.lastScore = 0;
    this.lastArmorActive = false;
    this.heartImages = [];
  }

  private buildParallax(): void {
    const cx = GAME_WIDTH / 2;
    this.bgFar = this.add
      .tileSprite(cx, GAME_HEIGHT / 2, GAME_WIDTH, GAME_HEIGHT, KEYS.park_bg_far)
      .setDepth(Depth.bgFar);
    this.bgNear = this.add
      .tileSprite(cx, GROUND_TOP_Y, GAME_WIDTH, 360, KEYS.park_bg_near)
      .setOrigin(0.5, 1)
      .setDepth(Depth.bgNear);
    this.groundTile = this.add
      .tileSprite(cx, GROUND_TOP_Y, GAME_WIDTH, GAME_HEIGHT - GROUND_TOP_Y, KEYS.ground_tile)
      .setOrigin(0.5, 0)
      .setDepth(Depth.ground);
    this.fgGrass = this.add
      .tileSprite(cx, GAME_HEIGHT, GAME_WIDTH, 140, KEYS.park_fg_grass)
      .setOrigin(0.5, 1)
      .setDepth(Depth.grass);
  }

  private buildGroundAndHero(): void {
    this.hero = new HeroDog(this, HERO_X, GROUND_TOP_Y);
    this.hero.setDepth(Depth.hero);
    this.hero.auraSprite.setDepth(Depth.aura);

    // Invisible static floor so the hero's jump arc lands cleanly.
    const ground = this.add
      .rectangle(GAME_WIDTH / 2, GROUND_TOP_Y, GAME_WIDTH, GAME_HEIGHT - GROUND_TOP_Y, 0x000000, 0)
      .setOrigin(0.5, 0);
    this.physics.add.existing(ground, true);
    this.physics.add.collider(this.hero, ground);
  }

  private buildSystems(): void {
    this.curve = new DifficultyCurve();
    this.spawner = new Spawner(this, this.curve, GROUND_TOP_Y, this.spawnX, this.recycleX);
  }

  private buildFinishLine(): void {
    this.finishLine = new FinishLine(this);
    this.finishLine.setDepth(Depth.entity);
    this.add.existing(this.finishLine);
    this.physics.add.existing(this.finishLine);
    this.finishLine.recycle(); // hidden until it's queued near LEVEL_LENGTH
  }

  private registerCollisions(): void {
    // Ticks: damage; when armored, the tick is CONSUMED for a powerful feel (§3.7).
    this.physics.add.overlap(
      this.hero,
      this.spawner.tickPool,
      (_h, obj) => this.onTick(obj as RunnerEntity),
      undefined,
      this,
    );
    // Bush/puddle: damage; ignored (not consumed) while invulnerable.
    this.physics.add.overlap(
      this.hero,
      this.spawner.obstaclePools,
      (_h, obj) => this.onObstacle(obj as RunnerEntity),
      undefined,
      this,
    );
    // Tablet: +score & +1 HP (capped).
    this.physics.add.overlap(
      this.hero,
      this.spawner.tabletPool,
      (_h, obj) => this.onTablet(obj as RunnerEntity),
      undefined,
      this,
    );
    // Armor: activate timed invulnerability + burst VFX.
    this.physics.add.overlap(
      this.hero,
      this.spawner.armorPool,
      (_h, obj) => this.onArmor(obj as RunnerEntity),
      undefined,
      this,
    );
    // Finish line: Victory.
    this.physics.add.overlap(this.hero, this.finishLine, () => this.endRun('win'), undefined, this);
  }

  private buildHud(): void {
    // Level-progress bar (frame asset + a dynamic fill inset within it).
    const barY = 16;
    const barW = 1180; // == ui_progress_bar asset width
    const barLeft = GAME_WIDTH / 2 - barW / 2;
    this.add.image(GAME_WIDTH / 2, barY, KEYS.ui_progress_bar).setDepth(Depth.hud);
    this.progressFill = this.add
      .rectangle(barLeft + 2, barY, barW - 4, 8, 0x6cc04a)
      .setOrigin(0, 0.5)
      .setDepth(Depth.hud);
    this.progressFill.scaleX = 0;

    // Score row (top-left).
    const rowY = 58;
    this.add.image(38, rowY, KEYS.ui_score_icon).setDepth(Depth.hud);
    this.scoreText = this.add
      .text(68, rowY, `${t('hud_score')}: 0`, {
        fontFamily: 'system-ui, sans-serif',
        fontSize: '26px',
        fontStyle: 'bold',
        color: '#20272e',
      })
      .setOrigin(0, 0.5)
      .setDepth(Depth.hud);

    // Hearts (below the score row).
    for (let i = 0; i < MAX_HP; i++) {
      this.heartImages.push(this.add.image(42 + i * 44, 100, KEYS.ui_heart_full).setDepth(Depth.hud));
    }
  }

  private buildInput(): void {
    // The WHOLE canvas is the jump zone (spec §3.2 / §10.4). Auto-run is always on.
    this.input.on(Phaser.Input.Events.POINTER_DOWN, () => this.hero.jump());
    this.input.keyboard
      ?.addKey(Phaser.Input.Keyboard.KeyCodes.SPACE)
      .on('down', () => this.hero.jump());
  }

  // ── Per-frame loop ────────────────────────────────────────────────────────────
  override update(time: number, delta: number): void {
    if (this.finished) return;

    const dt = delta / 1000;
    this.elapsedMs += delta;

    const progress = this.curve.progress(this.distance);
    const worldSpeed = this.curve.speed(progress);
    this.distance += worldSpeed * dt;

    this.scrollParallax(worldSpeed, dt);
    this.spawner.update(this.distance, worldSpeed, progress);
    this.updateFinishLine(worldSpeed);

    this.hero.tick(time);
    this.updateScore();
    this.updateHud(progress);
    this.emitArmor(time);

    // Deterministic Victory: the finish line has reached the hero.
    if (this.finishSpawned && this.finishLine.active && this.finishLine.x <= HERO_X) {
      this.endRun('win');
    }
  }

  private scrollParallax(worldSpeed: number, dt: number): void {
    this.bgFar.tilePositionX += worldSpeed * PARALLAX_FACTOR_FAR * dt;
    this.bgNear.tilePositionX += worldSpeed * PARALLAX_FACTOR_NEAR * dt;
    this.groundTile.tilePositionX += worldSpeed * PARALLAX_FACTOR_GROUND * dt;
    this.fgGrass.tilePositionX += worldSpeed * PARALLAX_FACTOR_GRASS * dt;
  }

  private updateFinishLine(worldSpeed: number): void {
    if (!this.finishSpawned) {
      if (this.distance >= LEVEL_LENGTH - this.approach) {
        this.finishLine.spawn(this.spawnX, GROUND_TOP_Y);
        this.finishSpawned = true;
        this.spawner.stopSpawning(); // nothing spawns past the finish (§3.9)
      }
      return;
    }
    if (this.finishLine.active) this.finishLine.setVelocityX(-worldSpeed);
  }

  private updateScore(): void {
    const survival = Math.floor((this.elapsedMs / 1000) * SCORE_SURVIVAL_PER_S);
    this.score = this.tabletScore + survival;
    if (this.score !== this.lastScore) {
      this.scoreText.setText(`${t('hud_score')}: ${this.score}`);
      this.events.emit(GameEvents.score, this.score);
      this.lastScore = this.score;
    }
  }

  private updateHud(progress: number): void {
    this.progressFill.scaleX = progress;
    this.events.emit(GameEvents.progress, progress);
    if (this.hero.hp !== this.lastHp) this.refreshHearts();
  }

  private refreshHearts(): void {
    const hp = this.hero.hp;
    this.heartImages.forEach((img, i) => {
      img.setTexture(i < hp ? KEYS.ui_heart_full : KEYS.ui_heart_empty);
    });
    this.events.emit(GameEvents.hp, hp);
    this.lastHp = hp;
  }

  private emitArmor(time: number): void {
    const active = this.hero.isArmored(time);
    const remainingMs = this.hero.armorRemaining(time);
    if (active !== this.lastArmorActive) {
      this.events.emit(GameEvents.armor, { active, remainingMs });
      this.lastArmorActive = active;
    }
  }

  // ── Collision handlers ─────────────────────────────────────────────────────────
  private onTick(tick: RunnerEntity): void {
    if (this.finished || !tick.active) return;
    const time = this.time.now;
    if (this.hero.isArmored(time)) {
      tick.recycle(); // consumed by the shield — feels powerful (§3.7)
      return;
    }
    if (this.hero.isInvulnerable(time)) return; // mid i-frame — ignore, don't consume
    if (this.hero.takeHit(time, TICK_DAMAGE)) {
      tick.recycle();
      this.onHeroDamaged();
    }
  }

  private onObstacle(obstacle: RunnerEntity): void {
    if (this.finished || !obstacle.active) return;
    const time = this.time.now;
    if (this.hero.isInvulnerable(time)) return; // armored or i-frame → no damage
    if (this.hero.takeHit(time, OBSTACLE_DAMAGE)) {
      this.onHeroDamaged(); // the dog bumps it; obstacle keeps scrolling
    }
  }

  private onTablet(tablet: RunnerEntity): void {
    if (this.finished || !tablet.active) return;
    tablet.recycle();
    this.tabletScore += TABLET_SCORE;
    this.hero.heal(TABLET_HEAL);
    this.refreshHearts();
  }

  private onArmor(armor: RunnerEntity): void {
    if (this.finished || !armor.active) return;
    armor.recycle();
    this.hero.activateArmor(this.time.now);
    this.spawnArmorBurst();
  }

  private onHeroDamaged(): void {
    this.cameras.main.shake(HIT_SHAKE_MS, HIT_SHAKE_INTENSITY);
    this.cameras.main.flash(HIT_FLASH_MS, 200, 60, 60);
    this.refreshHearts();
    if (this.hero.hp <= 0) this.endRun('lose');
  }

  /** One-shot pickup burst VFX (rare — not pooled; tween-then-destroy). */
  private spawnArmorBurst(): void {
    const burst = this.add
      .image(this.hero.x, this.hero.y - HERO_BODY_HEIGHT * 0.55, KEYS.vfx_armor_burst)
      .setDepth(Depth.aura);
    this.tweens.add({
      targets: burst,
      scale: { from: 0.5, to: 1.4 },
      alpha: { from: 1, to: 0 },
      duration: 380,
      ease: 'Quad.out',
      onComplete: () => burst.destroy(),
    });
  }

  // ── Termination ────────────────────────────────────────────────────────────────
  private endRun(result: 'win' | 'lose'): void {
    if (this.finished) return;
    this.finished = true;

    if (result === 'win') this.hero.victory();
    else this.hero.defeat();

    this.spawner.freeze();
    if (this.finishLine.active) this.finishLine.setVelocityX(0);

    const payload: FinishGameParams = {
      result,
      score: this.score,
      duration_s: Math.round(this.elapsedMs / 1000),
    };
    track('finish_game', payload);
    this.events.emit(GameEvents.runEnd, payload);

    // Let the win/lose pose read, then hand off with the EXACT placeholder payload.
    this.time.delayedCall(RESULTS_HANDOFF_DELAY_MS, () => {
      this.scene.start(SceneKey.Results, payload);
    });
  }

  private cleanup(): void {
    // Tweens/timers/display objects are scene-scoped and auto-destroyed; destroy the
    // pools explicitly so re-entering Game (play again) never leaks or double-fires.
    this.spawner.destroy();
    this.heartImages = [];
  }
}

