1	import Phaser from 'phaser';
2	
3	/**
4	 * RunnerEntity — shared base for every POOLED, world-scrolling entity (ticks,
5	 * tablets, obstacles, armor pickups, finish line).
6	 *
7	 * Pooling contract (spec §10.1 — no per-spawn GC churn):
8	 *  - Instances live in a `Phaser.Physics.Arcade.Group` (the pool) and are reused.
9	 *  - `group.get()` hands back a dead instance (or constructs one up to maxSize);
10	 *    the scene/spawner then calls `spawn(x, y)` to make it live at a position.
11	 *  - `recycle()` disables the body + hides it, returning it to the pool for reuse.
12	 *
13	 * Horizontal motion is driven by the Spawner setting `body.velocity.x` to the
14	 * current world speed each frame, so entities stay in lock-step with the parallax
15	 * and the distance metric (1 world unit == 1 px). None of these entities use
16	 * gravity — they float at their spawn Y and scroll left.
17	 */
18	export abstract class RunnerEntity extends Phaser.Physics.Arcade.Sprite {
19	  /** Reactivate this pooled entity at (x, y) with a live, gravity-free body. */
20	  spawn(x: number, y: number): this {
21	    // enableBody(reset, x, y, enableGameObject, showGameObject)
22	    this.enableBody(true, x, y, true, true);
23	    this.setActive(true);
24	    this.setVisible(true);
25	    this.setScale(1);
26	    this.setAlpha(1);
27	    this.setAngle(0);
28	
29	    const body = this.body as Phaser.Physics.Arcade.Body;
30	    body.setAllowGravity(false);
31	    body.setVelocity(0, 0);
32	    this.configureBody(body);
33	    return this;
34	  }
35	
36	  /** Return to the pool: disable body, hide, deactivate (so `group.get` reuses it). */
37	  recycle(): void {
38	    if (!this.active) return;
39	    // disableBody(disableGameObject, hideGameObject)
40	    this.disableBody(true, true);
41	  }
42	
43	  /** Whether this entity has scrolled far enough off-screen to be recycled. */
44	  isOffscreenLeft(recycleX: number): boolean {
45	    return this.active && this.x < recycleX;
46	  }
47	
48	  /**
49	   * Size/position the Arcade body once it is live. Default: a centered box scaled
50	   * to `hitboxScale` of the art frame — forgiving for the player. Subclasses may
51	   * override for a non-centered or full-height body (e.g. the finish line).
52	   */
53	  protected configureBody(body: Phaser.Physics.Arcade.Body): void {
54	    const scale = this.hitboxScale();
55	    body.setSize(this.width * scale, this.height * scale, true);
56	  }
57	
58	  /** Fraction of the art frame used for the (centered) hitbox. */
59	  protected abstract hitboxScale(): number;
60	}
